using Blazorise.DataGrid;
using Setak.IMS.Blazor.UI.Components.SimpleLists;
using Setak.IMS.Classes.DTOs.Reg;

namespace Setak.IMS.Blazor.UI.Components.Selectors;

public partial class ProvinceSelector : ComponentBase
{
    //---------------------- Variables --------------------------

    private List<ProvinceDto> ProvinceList { get; set; } = [];
    private HttpResult<IEnumerable<ProvinceDto>>? httpResult;

    //---------------------- Injections -------------------------

    [Inject] private IRegionClient RegionClient { get; set; }


    //---------------------- Refrences --------------------------

    private GenericSelector<List<Dictionary<int, string>>> selector;
    private ProvinceSimpleList _provinceSimpleList;


    //------------------------ Parameters ---------------------------

    [Parameter] public DataGridSelectionMode SelectionMode { get; set; }
    [Parameter] public bool ReadOnly { get; set; } = false;

    [Parameter] public bool ShowCheckbox { get; set; }

    [Parameter] public EventCallback<ProvinceDto> OnSelectItem { get; set; }
    [Parameter] public EventCallback<List<Dictionary<int, string>>> OnSelectItems { get; set; }
<|editable_region_start|>
    [Parameter] public string AuthorizePolicy { get; set; }

    [Parameter] public short CountryId { get; set; }

    //------------------- Protected Methods ----------------------
    protected override Task OnInitializedAsync()
    {
        _ = LoadGridDataAsync();
        return base.OnInitializedAsync();
    }

    //-------------------- Private Methods ----------------------

    private async Task LoadGridDataAsync()
    {
        try
        {
            await InvokeAsync(StateHasChanged);

            httpResult = await RegionClient.ProvinceListAsync(CountryId<|user_cursor_is_here|>);
            if (httpResult.IsSucceeded)
            {
                ProvinceList = httpResult.Data.ToList() ?? [];
            }

            StateHasChanged();
        }
        catch (Exception ex)
        {
            ErrorState.SetError(ex);
        }
        finally
        {
            await InvokeAsync(StateHasChanged);
        }
    }

    public async Task ShowModal() => await selector.Show();

    public Task HideModal() => selector.Hide();
<|editable_region_end|>


    private async Task OnFinalSelect()
    {
        switch (SelectionMode)
        {
            default:
            case DataGridSelectionMode.Single:
                var item = _provinceSimpleList.GetSelectedItem();
                if (item != null)
                {
                    await OnSelectItem.InvokeAsync(item);
                }

                break;
            case DataGridSelectionMode.Multiple:
                var items = _provinceSimpleList.GetSelectedItems();
                if (items.Any())
                {
                    await OnSelectItems.InvokeAsync(items);
                }

                break;
        }
    }
}
